base=c2base.base
R=Path(__file__).resolve().parents[2]
C1=R/'reading/french/c1/passages.jsonl'; C2=R/'reading/french/c2/passages.jsonl'; SCHEMA=R/'reading/schema/passage.schema.json'
LOCK=R/'reading/audit/french_c2_unit05_frontier_lock.json'; PLAN=R/'reading/audit/french_c2_unit06_plan.json'; SEL=R/'reading/audit/french_c2_unit06_target_selection.json'

USE={
'arrêt':'Un « arrêt » est ici une décision juridictionnelle qui tranche une question selon des règles de compétence et de procédure; son intérêt analytique est de distinguer la décision de contrôle de la préférence personnelle du décideur.',
'tribunal':'Un « tribunal » est une institution chargée d’examiner certains différends ou décisions. Dans le scénario, il ne remplace pas l’administration : il contrôle des questions définies, avec des pouvoirs et des limites propres.',
'examen':'L’« examen » désigne une vérification structurée des motifs, de la procédure ou des effets d’une décision; l’existence d’un examen n’implique pas automatiquement que toute décision initiale puisse être refaite de zéro.',
'annuler':'« Annuler » une décision signifie lui retirer son effet dans les conditions prévues. Le contrôle peut aussi conduire à corriger une procédure ou à renvoyer la question sans imposer lui-même le résultat final.',
'cour':'Une « cour » désigne ici une juridiction de contrôle. Le terme sert à comparer les niveaux de décision sans supposer que l’échelon supérieur possède toujours une meilleure information sur les faits locaux.',

'participer':'« Participer » signifie prendre part à un processus défini; la participation peut fournir de l’information ou de la légitimité, mais sa valeur dépend de qui peut réellement entrer dans le processus et de ce qui est fait des contributions.',
'volonté':'La « volonté » collective ne se lit pas directement dans une seule réunion. Des préférences peuvent être intenses, changeantes ou incompatibles, et une procédure doit expliquer comment elle transforme des expressions individuelles en décision commune.',
'rencontre':'Une « rencontre » publique crée un espace d’échange, mais elle sélectionne aussi les personnes disponibles à un lieu et une heure donnés. L’analyse distingue donc la qualité du dialogue de sa représentativité statistique.',
'nombreux':'Le fait que des participants soient « nombreux » renseigne sur l’ampleur d’une mobilisation sans suffire à établir que leurs préférences représentent toute la population concernée.',
'social':'Un effet « social » concerne ici les relations, usages et conséquences partagées au sein d’une collectivité; le mot ne sert pas d’étiquette partisane mais de catégorie de conséquences à comparer avec les coûts individuels et administratifs.',

'supérieur':'Un « supérieur » possède une autorité hiérarchique déterminée, mais l’autorité formelle ne garantit ni expertise locale ni information complète. La délégation précise donc ce qui peut être décidé à chaque niveau.',
'professionnel':'Un agent « professionnel » agit selon des compétences, procédures et responsabilités liées à sa fonction. La professionnalisation peut stabiliser l’exécution tout en créant un besoin de contrôle lorsque l’expertise devient difficile à évaluer de l’extérieur.',
'former':'« Former » des agents signifie développer des compétences et des normes de décision. La formation réduit certaines erreurs sans supprimer les conflits d’objectifs ni la nécessité de règles de recours.',
'emploi':'L’« emploi » désigne ici une fonction occupée dans une organisation. Séparer la personne de l’emploi permet d’analyser les incitations attachées au poste plutôt que d’attribuer chaque résultat au caractère individuel de l’agent.',
'ajouter':'« Ajouter » une étape de validation peut réduire un type d’erreur tout en augmentant les délais et les coûts de coordination. Une procédure supplémentaire doit donc être évaluée par son effet marginal, pas par l’idée abstraite que davantage de contrôle est toujours préférable.',

'journaliste':'Un « journaliste » peut demander des documents, comparer des versions et rendre une décision visible à un public plus large. Ce rôle d’observation reste distinct du pouvoir formel de décider ou de sanctionner.',
'couverture':'La « couverture » médiatique désigne l’attention et le cadrage accordés à un sujet. Une forte couverture peut accroître la surveillance sans garantir que les cas les plus importants reçoivent proportionnellement le plus d’attention.',
'note':'Une « note » administrative consigne une information, une justification ou une instruction. Elle devient utile à la reconstitution d’une décision seulement si son auteur, sa date, son objet et sa relation avec les autres pièces peuvent être établis.',
'reçu':'Un document « reçu » prouve qu’une information a été transmise ou qu’une opération a été enregistrée; il ne prouve pas à lui seul que son contenu a été compris, vérifié ou utilisé dans la décision finale.',
'insister':'« Insister » sur un fait augmente sa saillance. L’analyse doit vérifier si cette insistance correspond à son poids réel dans la décision ou si elle détourne l’attention de facteurs moins visibles mais plus déterminants.',

'menace':'Une « menace » est un événement ou un comportement susceptible de causer un dommage. Une politique de prévention doit distinguer la gravité possible de la probabilité, faute de quoi les scénarios les plus frappants peuvent absorber toutes les ressources.',
'cible':'Une « cible » est un résultat mesurable choisi pour orienter l’action. Une cible facilite la coordination mais peut aussi déplacer l’effort vers ce qui est compté au détriment de dimensions plus difficiles à mesurer.',
'unité':'Une « unité » administrative est un niveau d’organisation auquel des ressources et des responsabilités sont attribuées. La performance locale ne se confond pas nécessairement avec la performance du système entier.',
'avenir':'L’« avenir » intervient ici comme horizon de décision : une institution choisit entre résultats immédiats et capacité à faire face à des situations futures incertaines.',
'souci':'Un « souci » public est une préoccupation qu’une procédure doit traduire en question analysable. Reconnaître le souci ne suffit pas encore à choisir la réponse : il faut comparer causes, options, coûts, droits et effets secondaires.'
}

EXTRA=[
"Une comparaison institutionnelle doit préciser son critère. Une procédure peut être plus rapide, une autre plus réversible, une troisième plus transparente. Dire qu’un modèle est simplement meilleur mélange ces dimensions. Le texte demande donc quel type d’erreur on cherche à réduire, quel coût supplémentaire on accepte et qui supporte ce coût.",
"Le scénario introduit aussi une distinction entre règle et mise en œuvre. Deux institutions peuvent adopter le même texte et produire des résultats différents si l’information, les délais, les ressources ou les incitations des agents diffèrent. Une critique utile localise ainsi le mécanisme au lieu d’attribuer tout écart au principe déclaré.",
"Une objection importante porte sur les effets de sélection. Les personnes qui utilisent une procédure de recours, participent à une consultation ou répondent à un indicateur ne constituent pas nécessairement un échantillon aléatoire. L’interprétation sépare donc ce que le groupe observé révèle directement de ce qu’on voudrait inférer sur l’ensemble de la population.",
"Le raisonnement ajoute enfin une condition de révision. Si une mesure censée réduire un problème améliore l’indicateur choisi sans modifier les conséquences qui justifiaient l’intervention, la cible était peut-être trop étroite. Une institution robuste accepte de réexaminer la mesure plutôt que de protéger la métrique.",
"La neutralité du cadre ne signifie pas absence de valeurs. Rapidité, égalité de traitement, autonomie, contrôle, prévisibilité et participation peuvent entrer en tension. Le texte les rend explicites afin de comparer les arbitrages sans transformer l’exercice en soutien d’un parti, d’un candidat ou d’une position électorale réelle."
]

def h(p): return subprocess.check_output(['git','hash-object',str(p)],text=True).strip()
def fit(ps,lo,hi):
 p=list(ps); t='\n\n'.join(p); i=0
 while len(t.split())<lo and i<len(EXTRA):
  p[-1]+=' '+EXTRA[i]; i+=1; t='\n\n'.join(p)
 if not lo<=len(t.split())<=hi: raise AssertionError(f'C2 Unit06 word band {len(t.split())} not {lo}-{hi}')
 return p,t

def bridge(fs):
 return 'Révision interprétative : '+', '.join(f'« {x} »' for x in fs)+'. Ces formes de l’unité précédente sont reprises pour transférer l’analyse du cadrage et de la lecture vers les mécanismes institutionnels.'

def qitems(s,forms):
 core=[
  ('main_claim',s['qclaim'],s['aclaim'],[forms[0]]),
  ('ambiguity_resolution',s['qamb'],s['aamb'],[forms[1]]),
  ('assumption',s['qassume'],s['aassume'],[forms[2]]),
  ('rhetorical_function',s['qrhet'],s['arhet'],[forms[3]]),
  ('stance',s['qstance'],s['astance'],[forms[4]])]
 return core+[('vocabulary_in_context',f'Quel rôle institutionnel joue « {f} » dans ce passage ?',USE[f],[f]) for f in forms]

def make(s,forms,reviews,prior,D,lo,hi,theme):
 ps=list(s['paras']); ps[1]+=' '+' '.join(USE[f] for f in forms); ps[2]+=' '+bridge(reviews); ps,text=fit(ps,lo,hi)
 P=base.prior(prior); new=[c2base.nt(f,text,D) for f in forms]; rev=[base.rev(f,P) for f in reviews]; ids={t['form']:t['id'] for t in new+rev}; q,a=base.qa(qitems(s,forms),ids)
 return {'id':s['id'],'language':'fr','cefr':'C2','unit':6,'sequence':s['seq'],'revision':1,'title':s['title'],'passage_type':s['ptype'],'genre':s['genre'],'domains':['educational','public','professional'],'topics':[theme]+s['topics'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':new,'review_lexical_targets':rev,'grammar_targets':[{'id':s['id']+'-g1','role':'integration','description':'integrate institutional conditionals, scope restrictions, concession and counterfactual comparison'}],'discourse_targets':[{'id':s['id']+'-d1','role':'integration','description':'reconstruct institutional mechanisms, competing criteria, review conditions and nonpartisan tradeoffs'}],'questions':q,'answer_key':a,'speed_training':{'timed':False,'benchmark_eligible':False,'comprehension_gate':0.8,'new_word_policy':'controlled','notes':'C2 Unit06 institutional reasoning without partisan advocacy.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['All institutions and cases are fictional or generic; no real party, candidate, election, or current political claim is advocated.']},'paired_text_group':None,'prerequisites':['French C2 Unit05'],'difficulty_notes_internal':'C2 institutional design, review, representation, delegation, transparency and metric tradeoffs.','reader_tags':['unit_role:'+s['ptype'],'generation_batch','french_c2_u06']}

def specs(): return [
{'id':'fr-c2-u06-p01','seq':31,'ptype':'instructional','genre':'comparative analysis','topics':['institutional review','appeal','decision authority'],'title':'Contrôler une décision n’est pas nécessairement la refaire','paras':["Une ville fictive autorise chaque année une installation lumineuse sur une place centrale. Un service administratif évalue la sécurité, le bruit et l’accès aux commerces. Cette année, le projet est refusé. Les organisateurs demandent qu’un organe indépendant puisse contrôler la décision. Le problème n’est pas de choisir un camp, mais de distinguer trois fonctions : décider d’abord, vérifier la procédure et corriger une erreur éventuelle.","Le premier modèle confie presque tout au service initial parce qu’il connaît le terrain et peut agir vite. Le second permet un contrôle plus large par une instance extérieure. La comparaison ne suppose pas que l’un soit toujours supérieur; elle demande quelles erreurs chacun détecte mieux et quels coûts il ajoute.","Dans un scénario, le service oublie d’appliquer un critère public de manière cohérente. Un contrôle extérieur peut alors identifier l’écart sans décider lui-même de la beauté du spectacle, de l’étoile choisie pour l’affiche, de l’odeur des installations temporaires ou de la valeur esthétique du tableau projeté. Ces détails rappellent que certains désaccords portent sur des faits vérifiables et d’autres sur des jugements confiés par la règle à l’autorité compétente.","Une objection affirme qu’un contrôle fort ralentit tout. L’autre répond qu’une décision rapide mais impossible à corriger peut créer des coûts plus élevés plus tard. Le texte construit donc un compromis : préciser les motifs de contrôle, les délais, les pouvoirs de correction et les situations où une erreur rend la décision invalide.","La conclusion distingue indépendance et omniscience. Une instance de contrôle peut être moins exposée au conflit d’intérêt mais moins informée des contraintes locales. Le meilleur dessin dépend alors de la question : vérifier une procédure, interpréter une règle, réexaminer un fait ou substituer son propre jugement. La comparaison gagne en précision lorsqu’elle nomme cette fonction au lieu de parler vaguement de davantage ou de moins de contrôle."],'qclaim':'Quelle distinction organise la comparaison des deux modèles ?','aclaim':'La distinction entre prendre la décision initiale, contrôler sa légalité ou sa procédure, et substituer un nouveau jugement au premier.','qamb':'Pourquoi un tribunal de contrôle n’est-il pas présenté comme automatiquement mieux informé ?','aamb':'Parce que son indépendance peut être plus grande alors que sa connaissance des faits locaux ou techniques peut être plus faible.','qassume':'Que faut-il préciser pour évaluer l’utilité d’un recours ?','aassume':'Le type d’erreur visé, les pouvoirs de correction, les délais et le coût de la procédure.','qrhet':'Pourquoi le texte sépare-t-il les jugements esthétiques des critères vérifiables ?','arhet':'Pour montrer que toutes les divergences ne justifient pas le même niveau de contrôle et que la compétence dépend de la règle applicable.','qstance':'Quelle position générale le passage adopte-t-il ?','astance':'Le contrôle institutionnel doit être calibré à la fonction et au type d’erreur plutôt que maximisé abstraitement.'},
{'id':'fr-c2-u06-p02','seq':32,'ptype':'reinforcement','genre':'policy critique','topics':['public participation','representation','consultation design'],'title':'Une salle pleine ne parle pas automatiquement au nom de toute la ville','paras':["Une municipalité fictive doit choisir l’usage d’un terrain vacant. Elle organise une réunion ouverte, un questionnaire et plusieurs petits ateliers. Les trois méthodes produisent des préférences différentes. La réunion soutient fortement un parc, le questionnaire répartit les réponses entre parc et logements, et les ateliers révèlent surtout des préoccupations sur l’accès et le bruit. Le texte critique l’idée qu’une seule procédure révèle directement une volonté collective déjà formée.","Chaque canal sélectionne différemment les participants et les informations. Une rencontre en soirée favorise les personnes disponibles; un questionnaire atteint davantage de monde mais permet moins de discussion; un atelier offre plus de profondeur avec un nombre réduit de participants.","Le scénario ajoute une difficulté : certains citoyens participent deux fois par des canaux différents. Compter les interventions comme si elles représentaient des personnes distinctes créerait un double artificiel. D’autres restent éloignés du processus malgré une forte présence des groupes organisés. Un point de vue inconnu peut donc manquer non parce qu’il est inexistant, mais parce que la procédure ne l’a pas capté. Aucun adieu rhétorique à la participation n’est nécessaire : le problème est de préciser ce qu’elle mesure.","Une objection soutient qu’aucune consultation ne sera parfaitement représentative. Le texte l’accepte, puis distingue imperfection et absence de méthode. On peut publier qui a participé, comparer plusieurs canaux, pondérer certaines informations avec prudence et expliquer quelles décisions restent de la responsabilité de l’institution élue ou mandatée.","La conclusion refuse deux simplifications opposées. Une foule ne devient pas toute la population, mais une procédure technique ne peut pas non plus ignorer l’information vécue que les participants apportent. Une critique équilibrée demande quelle fonction la participation remplit : découvrir des conséquences, tester des options, mesurer une préférence ou créer un espace de justification réciproque."],'qclaim':'Pourquoi plusieurs formes de consultation peuvent-elles produire des résultats différents ?','aclaim':'Parce qu’elles sélectionnent des participants, des niveaux de détail et des modes d’expression différents.','qamb':'Quelle différence le texte établit-il entre participation et représentativité ?','aamb':'Participer fournit une voix ou une information; être représentatif exige en plus de savoir comment le groupe observé se rapporte à la population concernée.','qassume':'Pourquoi le double comptage est-il analytiquement important ?','aassume':'Parce qu’il peut transformer plusieurs contributions d’une même personne en apparence de soutien provenant de personnes différentes.','qrhet':'Quel rôle joue la comparaison réunion-questionnaire-ateliers ?','arhet':'Elle montre que le choix du canal fait partie du mécanisme de consultation et non un simple détail logistique.','qstance':'Quelle position le texte adopte-t-il sur les consultations imparfaites ?','astance':'Elles restent utiles si leur fonction, leur sélection et leurs limites sont rendues explicites au lieu d’être présentées comme une volonté totale.'},
{'id':'fr-c2-u06-p03','seq':33,'ptype':'interleaved','genre':'argument reconstruction','topics':['administrative delegation','professional discretion','hierarchy'],'title':'Déléguer une décision déplace aussi l’information et la responsabilité','paras':["Une agence fictive attribue de petites subventions techniques. Le règlement fixe les objectifs généraux mais laisse aux agents le soin d’évaluer la faisabilité de chaque dossier. Un débat oppose deux propositions : centraliser davantage les décisions chez les responsables hiérarchiques, ou accorder plus de marge aux agents qui examinent directement les projets. Le passage reconstruit les deux arguments avant d’en tester les présupposés.","L’argument pour la centralisation insiste sur la cohérence : un supérieur peut comparer les dossiers, corriger des écarts et rendre une doctrine commune visible. L’argument pour la délégation insiste sur l’expertise et le temps : un professionnel proche du dossier peut traiter des détails que la hiérarchie ne voit qu’après résumé.","La difficulté apparaît lorsque le discours transforme une différence de fonction en jugement de valeur. Donner un titre plus élevé à un poste ne prouve pas qu’il possède l’information pertinente; nommer un agent expert ne prouve pas davantage que son jugement doit être sans contrôle. Une instruction directe peut être claire et néanmoins mal adaptée à un cas. Justement parce que les niveaux disposent d’informations différentes, l’organisation doit préciser ce qui remonte, ce qui reste local et comment une erreur peut être contestée.","Une objection ajoute que davantage de formation suffit à résoudre la tension. Former les agents améliore la qualité moyenne, mais ne supprime ni les objectifs concurrents ni les cas nouveaux. Ajouter une validation systématique peut réduire certaines erreurs tout en créant un goulot d’étranglement. L’emploi institutionnel de chaque acteur détermine alors quelles incitations et quelles responsabilités accompagnent son pouvoir.","La conclusion reconstruit un compromis conditionnel. Les décisions routinières et réversibles peuvent être déléguées avec des critères clairs; les décisions rares, coûteuses ou difficiles à corriger peuvent exiger un contrôle supplémentaire. Ce n’est pas la hiérarchie seule qui décide du bon niveau, mais la combinaison de l’expertise, du coût de l’erreur, de la réversibilité et de la capacité à apprendre des recours."],'qclaim':'Quels avantages concurrents justifient centralisation et délégation ?','aclaim':'La centralisation favorise cohérence et comparaison, tandis que la délégation peut exploiter l’expertise locale et réduire les coûts de remontée de l’information.','qamb':'Pourquoi le titre hiérarchique ne suffit-il pas à déterminer le meilleur décideur ?','aamb':'Parce que l’autorité formelle et la possession de l’information pertinente sont deux propriétés différentes.','qassume':'Quand une validation supplémentaire devient-elle plus justifiable ?','aassume':'Lorsque l’erreur possible est coûteuse, difficile à corriger ou nécessite une comparaison que le niveau local ne peut pas effectuer seul.','qrhet':'Pourquoi le passage reconstruit-il d’abord les deux arguments ?','arhet':'Pour éviter de caricaturer un camp et identifier les mécanismes réels — cohérence, expertise, information et réversibilité — avant d’évaluer les options.','qstance':'Quelle solution institutionnelle est proposée ?','astance':'Une délégation conditionnelle où le niveau de contrôle dépend du type de décision plutôt qu’une centralisation ou une autonomie absolue.'},
{'id':'fr-c2-u06-p04','seq':34,'ptype':'transfer','genre':'comparative analysis','topics':['transparency','public records','media scrutiny'],'title':'Rendre un document public n’est pas encore rendre une décision compréhensible','paras':["Deux organismes fictifs publient des informations sur leurs décisions. Le premier met en ligne chaque document brut dès sa création. Le second publie moins de pièces, mais ajoute une chronologie, les motifs de la décision et un index reliant les documents. Les deux revendiquent la transparence. Le passage compare disponibilité, traçabilité et compréhension sans supposer qu’une quantité maximale de fichiers constitue automatiquement la meilleure politique.","Un journaliste peut utiliser les documents pour reconstituer une séquence, mais la couverture dépend de ce qui est repérable et comparable. Une note sans date ou un fichier reçu sans contexte peut être authentique tout en étant difficile à relier au résultat final. Insister sur le volume publié peut donc masquer une faible capacité de vérification.","Le transfert depuis l’analyse littéraire est volontaire : suivre le fil d’une décision ressemble à suivre un motif dans un texte, mais l’objet de preuve change. Ici, il ne faut pas inventer une relation simplement parce que deux pièces se ressemblent; il faut fouiller les métadonnées, les dates, les signatures et les références. La taille d’un dossier n’est pas sa qualité explicative.","Une objection affirme qu’un index ou un résumé permet à l’institution de contrôler le récit. Le texte répond qu’un bon système conserve aussi l’accès aux documents sources et rend la méthode de classement vérifiable. L’autre extrême — publier sans structure — peut imposer un coût de recherche si élevé que la transparence devient théorique pour la plupart des observateurs.","La conclusion distingue trois objectifs : rendre les pièces accessibles, permettre de relier une décision à ses motifs et laisser un tiers vérifier la reconstruction. Une politique de documentation robuste cherche un compromis entre ces fonctions, la protection légitime de certaines informations et les coûts de conservation."],'qclaim':'Pourquoi publier davantage de fichiers n’est-il pas nécessairement plus transparent ?','aclaim':'Parce que des documents sans contexte, index, date ou relation explicite peuvent être disponibles tout en restant difficiles à relier à la décision.','qamb':'Quelle différence sépare disponibilité et compréhension ?','aamb':'La disponibilité donne accès aux pièces; la compréhension exige en plus de pouvoir identifier leur fonction et leur relation avec la décision.','qassume':'Pourquoi conserver les documents sources avec les résumés ?','aassume':'Pour permettre à un tiers de vérifier si le classement ou le résumé reflète fidèlement les pièces originales.','qrhet':'Quel rôle joue la comparaison entre suivi d’un motif littéraire et suivi d’une décision ?','arhet':'Elle transfère une méthode de reconstruction tout en précisant que les critères de preuve institutionnelle sont documentaires et vérifiables.','qstance':'Quelle conception de la transparence est défendue ?','astance':'Une transparence qui combine accès, traçabilité et possibilité de vérification plutôt que volume brut de publication.'},
{'id':'fr-c2-u06-p05','seq':35,'ptype':'integration','genre':'policy critique','topics':['performance targets','risk allocation','institutional adaptation'],'title':'Une bonne cible peut devenir mauvaise lorsqu’elle remplace le problème qu’elle devait mesurer','paras':["Une administration fictive veut réduire le délai de traitement de demandes importantes. Elle fixe une cible moyenne de vingt jours pour chaque unité. Les délais chutent rapidement. Pourtant, les dossiers complexes sont de plus en plus classés dans une catégorie séparée qui n’entre pas dans la moyenne. L’indicateur s’améliore tandis qu’un souci initial — l’attente des cas difficiles — reste presque inchangé.","La critique ne conclut pas qu’une cible est inutile. Une cible rend une priorité visible, permet de comparer des périodes et attire l’attention sur une menace de retard. Mais lorsqu’un indicateur devient lui-même l’objet de récompenses ou de sanctions, les agents peuvent modifier ce qui est compté plutôt que la conséquence recherchée.","La vision du système importe alors davantage que le goût pour un chiffre simple. La presse pourrait saisir une amélioration spectaculaire de la moyenne et pourtant manquer la distribution des cas. Effacer les dossiers complexes du dénominateur change le récit sans changer nécessairement l’expérience du public. L’avenir du dispositif dépend donc de sa capacité à détecter les déplacements de charge entre catégories.","Une objection propose d’ajouter toujours plus d’indicateurs. Cela réduit certains angles morts mais peut créer un système lourd où chaque unité optimise un tableau différent. Le texte suggère plutôt une architecture à plusieurs niveaux : une mesure principale, quelques indicateurs de garde-fou et un examen périodique des cas qui échappent aux métriques.","La conclusion distingue direction et définition du succès. Une cible peut orienter l’action sans constituer la totalité de l’objectif. Elle doit rester reliée au souci qui l’a motivée et être révisée lorsque les comportements d’adaptation la rendent moins informative. Une institution apprend non seulement en atteignant ses chiffres, mais en observant comment ses chiffres changent les décisions."],'qclaim':'Quel problème central apparaît lorsque la cible de délai devient un objet de gestion ?','aclaim':'Les acteurs peuvent améliorer l’indicateur en changeant la classification des dossiers sans réduire le problème initial pour les cas difficiles.','qamb':'Pourquoi une cible utile n’est-elle pas identique à la définition complète du succès ?','aamb':'Parce qu’elle mesure une dimension choisie et peut perdre de l’information sur d’autres conséquences importantes.','qassume':'Pourquoi des indicateurs de garde-fou sont-ils proposés ?','aassume':'Pour détecter si l’amélioration de la mesure principale déplace les coûts ou les cas difficiles vers des catégories non mesurées.','qrhet':'Quel rôle joue l’exemple de la moyenne des délais ?','arhet':'Il montre concrètement comment une métrique peut s’améliorer alors que la distribution sous-jacente conserve le problème qui motivait la politique.','qstance':'Quelle politique de mesure est défendue ?','astance':'Utiliser des cibles comme outils révisables reliés aux conséquences réelles, avec des garde-fous et une surveillance des adaptations.'}]

def checkpoint(groups,D,lo,hi,theme,prior):
 forms=[f for k in ['p01','p02','p03','p04','p05'] for f in groups[k]]
 ps=[
 "Le checkpoint présente cinq institutions fictives confrontées à des choix distincts : recours contre une décision, consultation publique, délégation professionnelle, publication de documents et cible de performance. Aucun cas n’appelle une préférence partisane. Le lecteur doit reconstruire les mécanismes, identifier les critères concurrents et dire quelle observation modifierait sa conclusion.",
 "La première étape sépare pouvoir, information et responsabilité. Une institution peut avoir le droit de décider sans posséder toute l’information; une autre peut observer sans pouvoir corriger; une troisième peut participer sans représenter statistiquement l’ensemble. Révision cumulative : "+'; '.join(f'« {f} »' for f in forms)+". Les mots sont réutilisés pour décrire précisément les fonctions au lieu de servir d’étiquettes politiques.",
 "La deuxième étape compare les erreurs possibles. Un contrôle trop faible peut laisser persister une décision irrégulière; un contrôle trop large peut ralentir des décisions réversibles. Une consultation étroite peut manquer certains groupes; une consultation massive peut agréger des réponses peu informées. Une cible trop simple peut déplacer l’effort; trop de mesures peuvent rendre la responsabilité illisible.",
 "La troisième étape construit un test contrefactuel. On modifie une seule caractéristique — délai de recours, canal de participation, seuil de délégation, indexation documentaire ou définition de la cible — puis on prédit quelle variable intermédiaire devrait changer si le mécanisme proposé est correct. Le lecteur distingue ainsi préférence institutionnelle et explication causale.",
 "La conclusion impose une règle de portée. Une solution adaptée à une décision rapide et réversible ne devient pas automatiquement un modèle pour une décision rare et irréversible. Une procédure qui améliore la participation d’un groupe ne prouve pas encore une représentation totale. Le checkpoint récompense donc la capacité à qualifier une recommandation, à expliciter ses valeurs et à annoncer les conditions de révision."
 ]
 ps,text=fit(ps,lo,hi); P=base.prior(prior); rev=[base.rev(f,P) for f in forms]; ids={t['form']:t['id'] for t in rev}
 items=[
 ('main_claim','Quelle méthode commune relie les cinq cas institutionnels ?','Séparer fonctions, mécanismes, critères concurrents et conditions de révision avant de recommander une architecture.',[forms[0]]),
 ('ambiguity_resolution','Pourquoi participation et représentation ne sont-elles pas synonymes ?','La participation décrit l’entrée dans un processus; la représentation exige une relation défendable entre les participants observés et la population concernée.',[forms[5]]),
 ('assumption','Pourquoi modifier une seule caractéristique dans le test contrefactuel ?','Pour isoler plus clairement le mécanisme supposé et vérifier quelle variable intermédiaire devrait changer.',[forms[12]]),
 ('rhetorical_function','Pourquoi le checkpoint compare-t-il plusieurs types d’erreur ?','Pour empêcher qu’un critère unique — vitesse, contrôle, participation ou transparence — soit traité comme s’il dominait toutes les autres valeurs institutionnelles.',[forms[20]]),
 ('synthesis','Quelle règle limite la portée d’une recommandation institutionnelle ?','Elle doit être liée au type de décision, aux erreurs visées, aux valeurs explicites et aux observations qui justifieraient une révision.',[forms[23]]),
 ('vocabulary_in_context',f'Quel rôle joue « {forms[2]} » dans le contrôle institutionnel ?',USE[forms[2]],[forms[2]]),
 ('vocabulary_in_context',f'Quel rôle joue « {forms[9]} » dans l’analyse des conséquences ?',USE[forms[9]],[forms[9]]),
 ('vocabulary_in_context',f'Quel rôle joue « {forms[16]} » dans la transparence ?',USE[forms[16]],[forms[16]]),
 ('vocabulary_in_context',f'Quel rôle joue « {forms[21]} » dans le pilotage ?',USE[forms[21]],[forms[21]]),
 ('register_style','Pourquoi le vocabulaire du checkpoint évite-t-il les étiquettes partisanes ?','Parce que l’objectif est de comparer des mécanismes et des arbitrages institutionnels génériques sans soutenir un parti, un candidat ou une position électorale réelle.',[forms[24]])]
 q,a=base.qa(items,ids)
 return {'id':'fr-c2-u06-p06','language':'fr','cefr':'C2','unit':6,'sequence':36,'revision':1,'title':'Checkpoint : comparer des institutions sans transformer l’analyse en slogan','passage_type':'checkpoint','genre':'argument reconstruction','domains':['educational','public','professional'],'topics':[theme,'cumulative institutional design'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':[],'review_lexical_targets':rev,'grammar_targets':[{'id':'fr-c2-u06-p06-g1','role':'integration','description':'integrate scope qualification, institutional conditionals and counterfactual testing'}],'discourse_targets':[{'id':'fr-c2-u06-p06-d1','role':'integration','description':'synthesize review, representation, delegation, transparency and metric adaptation without partisan advocacy'}],'questions':q,'answer_key':a,'speed_training':{'timed':True,'benchmark_eligible':True,'comprehension_gate':0.8,'new_word_policy':'none','notes':'C2 Unit06 zero-new institutional checkpoint.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['Fictional/generic institutions only; no partisan advocacy or current political factual claims.']},'paired_text_group':None,'prerequisites':['French C2 Unit06 P01-P05'],'difficulty_notes_internal':'C2 cumulative institutional design and nonpartisan policy reasoning.','reader_tags':['unit_role:checkpoint','generation_batch','french_c2_u06']}

